package main

import ("encoding/json";"errors";"fmt";"os";"path/filepath";"sync";"time")

const dataSchemaVersion = 2
type Preferences struct { Theme string `json:"theme"`; DefaultQuizSize int `json:"defaultQuizSize"`; PracticeMode string `json:"practiceMode"`; State string `json:"state"`; District string `json:"district,omitempty"`; InterviewDate string `json:"interviewDate,omitempty"`; InterviewDateOfficial bool `json:"interviewDateOfficial,omitempty"` }
type Attempt struct { ID string `json:"id"`; CompletedAt time.Time `json:"completedAt"`; Mode string `json:"mode"`; QuestionCount int `json:"questionCount"`; QuestionOrder []int `json:"questionOrder"`; BankRevision string `json:"bankRevision"`; Result QuizResult `json:"result"` }
type CurrentAnswerRecord struct { QuestionID int `json:"questionId"`; Answers []string `json:"answers"`; Status string `json:"status"`; Source string `json:"source"`; SourceURL string `json:"sourceUrl"`; VerifiedAt *time.Time `json:"verifiedAt,omitempty"`; Suggested []string `json:"suggested,omitempty"`; SuggestionAt *time.Time `json:"suggestionAt,omitempty"`; Warning string `json:"warning,omitempty"` }
type Profile struct { ID string `json:"id"`; Name string `json:"name"`; CreatedAt time.Time `json:"createdAt"`; LastUsedAt time.Time `json:"lastUsedAt"`; Preferences Preferences `json:"preferences"`; Current *Session `json:"current,omitempty"`; History []Attempt `json:"history"`; CurrentAnswers map[int]CurrentAnswerRecord `json:"currentAnswers"` }
// Legacy fields are retained only to migrate Stage 3 history safely.
type AppData struct { SchemaVersion int `json:"schemaVersion"`; ActiveProfileID string `json:"activeProfileId"`; Profiles []Profile `json:"profiles"`; Preferences Preferences `json:"preferences"`; Current *Session `json:"current,omitempty"`; History []Attempt `json:"history"` }
type dataStore struct { path string; mu sync.Mutex; data AppData }
func defaultPreferences() Preferences{return Preferences{Theme:"system",DefaultQuizSize:20,PracticeMode:"multiple-choice"}}
func newProfile(name string) Profile { now:=time.Now(); return Profile{ID:newID(),Name:name,CreatedAt:now,LastUsedAt:now,Preferences:defaultPreferences(),History:[]Attempt{},CurrentAnswers:map[int]CurrentAnswerRecord{}} }
func userDataPath() (string,error) { dir,err:=os.UserConfigDir();if err!=nil{return "",err};return filepath.Join(dir,"USCivicsPractice","history.json"),nil }
func normalizeData(d *AppData) error { if d.SchemaVersion==1 { p:=newProfile("My Practice");p.Preferences=d.Preferences;if p.Preferences.Theme==""{p.Preferences=defaultPreferences()};p.Current=d.Current;p.History=d.History;d.SchemaVersion=dataSchemaVersion;d.ActiveProfileID=p.ID;d.Profiles=[]Profile{p};d.Current=nil;d.History=nil;return nil };if d.SchemaVersion!=dataSchemaVersion{return fmt.Errorf("history uses incompatible schema version %d",d.SchemaVersion)};if len(d.Profiles)==0{return errors.New("profile data is empty")};found:=false;for i:=range d.Profiles{p:=&d.Profiles[i];if p.Preferences.Theme==""{p.Preferences=defaultPreferences()};if p.History==nil{p.History=[]Attempt{}};if p.CurrentAnswers==nil{p.CurrentAnswers=map[int]CurrentAnswerRecord{}};if p.ID==d.ActiveProfileID{found=true}};if !found{d.ActiveProfileID=d.Profiles[0].ID};return nil }
func loadStore() (*dataStore,error) { path,err:=userDataPath();if err!=nil{return nil,err}; s:=&dataStore{path:path,data:AppData{SchemaVersion:dataSchemaVersion}};raw,err:=os.ReadFile(path);if errors.Is(err,os.ErrNotExist){p:=newProfile("My Practice");s.data.ActiveProfileID=p.ID;s.data.Profiles=[]Profile{p};return s,nil};if err!=nil{return nil,err};if err=json.Unmarshal(raw,&s.data);err!=nil{return nil,fmt.Errorf("could not read existing history at %s: %w",path,err)};if err=normalizeData(&s.data);err!=nil{return nil,fmt.Errorf("history at %s: %w",path,err)};return s,nil }
func (s *dataStore) active() *Profile {for i:=range s.data.Profiles{if s.data.Profiles[i].ID==s.data.ActiveProfileID{return &s.data.Profiles[i]}};return nil}
func (s *dataStore) save() error { s.mu.Lock();defer s.mu.Unlock();return s.saveLocked() }
func (s *dataStore) saveLocked() error { if err:=os.MkdirAll(filepath.Dir(s.path),0700);err!=nil{return err}; raw,err:=json.MarshalIndent(s.data,"","  ");if err!=nil{return err}; tmp:=s.path+".tmp";if err=os.WriteFile(tmp,raw,0600);err!=nil{return err};if err=os.Chmod(tmp,0600);err!=nil{return err};return os.Rename(tmp,s.path) }
